/// Settled attack coefficient for a (fractional) index in -64..=64.
#[inline]
pub fn settled_attack_coeff(index: f32) -> f32 {
    lookup(&ATTACK_BITS, index)
}

/// Settled decay / release coefficient (`1 - c` is the per-pass decay) for an index in -64..=64.
#[inline]
pub fn settled_decay_release_coeff(index: f32) -> f32 {
    lookup(&DECAY_BITS, index)
}

#[cfg(test)]
mod tests {
    use super::*;

    const CSV: &str = include_str!(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../docs/research/data/synth-env-rates-settled.csv"
    ));

    #[test]
    fn tables_equal_the_settled_csv() {
        let rows: Vec<Vec<&str>> = CSV
            .lines()
            .skip(1)
            .map(|l| l.trim().split(',').collect())
            .collect();
        assert_eq!(rows.len(), ATTACK_BITS.len());
        let bits = |s: &str| u32::from_str_radix(s.trim_start_matches("0x"), 16).unwrap();
        for (i, r) in rows.iter().enumerate() {
            assert_eq!(r[0].parse::<i32>().unwrap(), i as i32 - 64, "index column");
            assert_eq!(ATTACK_BITS[i], bits(r[4]), "attack[{i}]");
            assert_eq!(DECAY_BITS[i], bits(r[5]), "decay[{i}]");
            let (dec, rel): (f32, f32) = (r[2].parse().unwrap(), r[3].parse().unwrap());
            assert_eq!(dec, rel, "decay and release share the table at {i}");
            assert_eq!(f32::from_bits(DECAY_BITS[i]), dec, "decay value[{i}]");
        }
    }

    #[test]
    fn tables_fall_smoothly_without_plateaus() {
        for i in -64..64 {
            let (a, b) = (i as f32, (i + 1) as f32);
            assert!(
                settled_attack_coeff(b) < settled_attack_coeff(a),
                "attack {i}"
            );
        }
        // Index 64 (the +0.5 clip) is off the curve: 1 - a is 5.0e-6, above index 63's 4.8e-6.
        for i in -64..63 {
            let (a, b) = (i as f32, (i + 1) as f32);
            let (ra, rb) = (
                1.0 - settled_decay_release_coeff(a),
                1.0 - settled_decay_release_coeff(b),
            );
            assert!(rb < ra, "decay {i}");
        }
    }

    #[test]
    fn settled_values_differ_from_the_stale_sweep_inside_its_plateaus() {
        use super::super::fw_env_rates::{attack_coeff, decay_release_coeff};
        assert_eq!(
            settled_attack_coeff(-64.0),
            attack_coeff(-64.0),
            "plateau anchor"
        );
        assert!((settled_attack_coeff(-60.0) / attack_coeff(-60.0) - 0.4310 / 0.9216).abs() < 1e-3);
        let (new, old) = (
            1.0 - settled_decay_release_coeff(-60.0),
            1.0 - decay_release_coeff(-60.0),
        );
        assert!(new < 0.6 * old, "decay rate {new} against the stale {old}");
        assert_eq!(settled_attack_coeff(f32::NAN), settled_attack_coeff(-64.0));
        assert_eq!(settled_attack_coeff(100.0), settled_attack_coeff(64.0));
    }
}
